from fastapi import APIRouter, Depends, HTTPException
from pydantic import BaseModel
from typing import List
import duckdb

router = APIRouter(prefix="/analytics/ingest")

class IngestBatch(BaseModel):
    rows: List[List[str]]

@router.post("/batch")
async def ingest_analytics_batch(
    batch: IngestBatch,
    duck_conn: duckdb.DuckDBPyConnection = Depends(get_duckdb_session),
    current_user: User = Depends(get_current_user)
):
    target_table = f"raw_events_tenant_{current_user.tenant_id}"
    try:
        appender = duck_conn.appender(target_table)
        for row in batch.rows:
            appender.append(row)
        appender.flush()
        appender.close()
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"Failed to append to table: {str(e)}")

    return {"status": "ingested", "table": target_table, "count": len(batch.rows)}
